const StoreAbort = `-- name: StoreAbort :many
SELECT member FROM fry_target WHERE attempt=$1 ORDER BY member
`

// Used by Abort in member_linux.go.
func (q *Queries) StoreAbort(ctx context.Context, attempt string) ([]string, error) {
	rows, err := q.db.Query(ctx, StoreAbort, attempt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var member string
		if err := rows.Scan(&member); err != nil {
			return nil, err
		}
		items = append(items, member)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

